function playerGrowth13(p,mode,facility,focus){
 let a=p.attributes13,intense=mode==='intensive',rest=mode==='rest',headroom=Math.max(0,p.potential-p.skill),freshness=clamp((95-p.fatigue)/80,0,1);
 // Diminishing returns; the same rule is applied to every contracted player.
 let growth=rest?0:(intense?.018:.009)*facility*(headroom/8)*freshness;
 p.skill=Math.min(p.potential,p.skill+growth);if(!rest)a[focus]=clamp(a[focus]+growth*2,40,99);
 p.fatigue=clamp(p.fatigue+(rest?-12:intense?4:-1));
 let target=rest?68:intense?82:75;p.form=clamp(p.form+(target-p.form)*.025+(rng()-.5)*.8,35,95);
 p.morale=clamp(p.morale+(rest?.5:intense?-.3:.05)+(p.active?0:-.2),20,98);
 if(!rest&&focus==='versatility'){let heroes=playerPool4(p);let h=heroes[(S.day+p.id)%heroes.length]?.hero;if(h)p.heroPractice13[h]=Math.min(20,(p.heroPractice13[h]||0)+.12*facility);}
}
