   if(!own&&S.day%28===0&&c.coach<95&&c.budget>600000){c.budget-=75000;c.coach=Math.min(95,c.coach+2);}
   if(!own&&c.facility<5&&c.budget>2000000){c.budget-=350000*c.facility;c.facility++;}
