offer=function(id,kind='rotation'){if(locked())return;init13();let p=S.players[id];if(!p||p.team===S.club)return;let q=transferTerms13(p,kind);openModal(`<div class="eyebrow">ПЕРЕГОВОРЫ</div><h1>${esc(p.name)}</h1><p>${p.profile13?esc(p.profile13.realName)+' · '+esc(p.profile13.country):ROLES[p.role]}</p><div class="actions">${btn('Ротация',`offer(${id},'rotation')`,kind==='rotation')}${btn('Место в основе',`offer(${id},'starter')`,kind==='starter')}${btn('Профиль',`profile(${id})`)}</div><p>Переход: <b>${cash(q.fee)}</b> · зарплата: <b>${cash(q.salary)}/нед.</b> · контракт 365 дней.</p><p>Амбиции игрока: ${Math.round(p.ambition13)} · уровень клуба: ${Math.round(strength(my()))}. ${kind==='starter'?'Подписание сразу заменит игрока этой позиции; прежний игрок перейдёт в резерв.':'Игрок войдёт в резерв и будет ожидать игрового времени.'}</p>${q.reason?'<p class="red">'+esc(q.reason)+'</p>':'<p class="green">Условия предварительно согласованы.</p>'}<div class="actions">${btn('Закрыть','closeModal()')}${btn('Подписать',`buy(${id},'${kind}')`,true,!!q.reason||S.budget<q.fee||owned().filter(x=>!x.active).length>=3)}</div>`);};
