const profileBase13=profile;profile=function(id){let p=S.players[id];if(!p)return;initPlayer13(p);profileBase13(id);$('modal').innerHTML=$('modal').innerHTML.replace(/Продать за [^<]+/g,'Освободить контракт');let d=p.profile13;let extra=d?`<section class="profile13"><h2>${esc(d.realName)}</h2><p>${esc(d.country)} · ${d.birth} · ${esc(d.bio)}</p><p>Свободный агент при введении v1.3 — условие этой карьеры. Рейтинг ${d.rating} — оценка игры.</p><p><a href="https://liquipedia.net/dota2/${d.wiki}" target="_blank" rel="noopener">Биография ↗</a> · <a href="https://www.dotabuff.com/esports/players/${d.account}" target="_blank" rel="noopener">Статистика и герои ↗</a></p><p class="sub">Карьерный срез героев проверен 16.10.2026; он может включать другие позиции и патчи.</p></section>`:'';extra+=`<section class="profile13"><h2>Стиль игрока</h2>${Object.entries(ATTR13).map(([k,n])=>bar(n,p.attributes13[k])).join('')}<p class="sub">Характеристики — модель симулятора. Линия влияет на стартовую экономику, механика и решения — на бой, командная игра — на координацию, пул — на комфорт героев.</p></section>`;$('modal').innerHTML+=extra;};
function fit13(p,t){let c=clubState13(t);return p.skill+(p.attributes13?.teamwork||80)*.025-Math.max(0,p.salary*20-c.budget)/100000;}
function reshuffleOptions13(t,used,closed){
 let c=clubState13(t),options=[];
 for(let old of roster(t)){
  let league=S.players.filter(p=>p.active&&p.team!==null&&p.role===old.role),roleLevel=avg(league.map(p=>p.skill));
  let need=Math.max(0,roleLevel-old.skill)*.35+Math.max(0,80-old.morale)*.05+Math.max(0,75-old.form)*.04;
  let weight=(1+need)/(1+(used[old.role]||0)*2)*(c.lastReshuffleRole13===old.role?.3:1);
  let agents=S.players.filter(p=>!p.retired&&p.team===null&&p.role===old.role&&p.id!==old.id&&p.salary*1.1*12<c.budget&&value(p)*.15<c.budget*.45&&(p.skill>=old.skill-2||c.budget<200000)).sort((a,b)=>fit13(b,t)-fit13(a,t));
  if(agents.length)options.push({old,p:agents[0],weight:weight*1.6,swap:false});
  // A thin free-agent pool must not confine all future windows to one position.
  // Two AI clubs may exchange comparable starters through paid releases/signings.
  let partners=S.players.filter(p=>p.active&&p.team!==null&&p.team!==t.id&&p.team!==S.club&&!closed.has(p.team)&&p.role===old.role&&Math.abs(p.skill-old.skill)<=3&&clubState13(S.teams[p.team]).lastResults.slice(-3).filter(Boolean).length<3&&c.budget>value(p)*.75+p.salary*12&&funds13(p.team)>value(old)*.75+old.salary*12);
  if(partners.length){let p=weighted4(partners,partners.map(p=>1/(1+Math.abs(p.skill-old.skill))));options.push({old,p,weight:weight*.8,swap:true});}
 }
 return options;
}
function signReshuffle13(p,team,fee,window){p.team=team;p.active=true;p.contract=365;p.salary=Math.round(p.salary*1.03);transferEntryV1(p,null,team,'sign',fee,window);let c=clubState13(S.teams[team]);c.chem=clamp(c.chem-8);c.lastReshuffleRole13=p.role;}
runReshuffleV1=function(){if(S.active||S.practice13)return false;init13();let window=S.reshuffleWindowsV1.length+1,moves=[],used=[0,0,0,0,0],closed=new Set();
 for(let t of S.teams.filter(t=>t.id!==S.club)){if(closed.has(t.id))continue;let c=clubState13(t),losses=c.lastResults.slice(-5).filter(x=>!x).length,prob=c.budget<200000?.65:losses>=3?.6:.12;if(rng()>prob)continue;
  let options=reshuffleOptions13(t,used,closed);if(!options.length)continue;let choice=weighted4(options,options.map(o=>o.weight)),{old,p}=choice;
  let reason=c.budget<200000?'Сокращение расходов':losses>=3?'Неудачные результаты':'Обновление состава';
  if(choice.swap){
   let partner=p.team,feeIn=Math.round(value(p)*.75),feeOut=Math.round(value(old)*.75);
   releasePlayerV1(old,{fee:feeOut,window});releasePlayerV1(p,{fee:feeIn,window});
   pay13(t.id,feeOut-feeIn,'Обмен игроками');pay13(partner,feeIn-feeOut,'Обмен игроками');
   signReshuffle13(p,t.id,feeIn,window);signReshuffle13(old,partner,feeOut,window);
   moves.push({team:t.id,out:old.id,in:p.id,role:old.role,reason},{team:partner,out:p.id,in:old.id,role:old.role,reason:'Обмен на той же позиции'});closed.add(partner);used[old.role]+=2;
  }else{
   let fee=Math.round(value(p)*.15);releasePlayerV1(old,{window});pay13(t.id,-fee,'Подписание свободного агента');signReshuffle13(p,t.id,fee,window);moves.push({team:t.id,out:old.id,in:p.id,role:old.role,reason});used[old.role]++;
  }
  closed.add(t.id);
 }
 S.reshuffleWindowsV1.unshift({id:window,day:S.day,moves});S.nextReshuffleV1=addMonthsV1(S.day,int(3,5));log('Окно решафлов №'+window+': '+moves.length+' замен по результатам, бюджету и доступным игрокам.');return true;};
