const modelBase13=modelView4;modelView4=function(){return head('МОДЕЛЬ / v1.3','События определяют результат','Оригинальная симуляция; коэффициенты не обучены на реплеях.')+`<section class="panel"><h2>Экономика и завершение карты</h2><p>Награды за убийства, фарм и объекты поступают без лимита изменения перевеса. Запрет на уничтожение трона после отставания снят. Победа требует сноса базы либо GG.</p><p>Разброс исполнения сохраняется. Характеристики игрока, комфорт героя, усталость, драфт, патч, предметы и локальный состав драки влияют на события. Сборки различаются по роли и герою и реагируют на контроль соперника; эффекты предметов упрощены.</p><p>Камбэк нужно заработать: убийства при отставании дают дополнительную награду участникам драки. Золото усиливает через предметы и опыт; отдельного множителя силы за общий перевес нет. Защита хайграунда помогает пережить осаду, а открытый объект можно атаковать при локальном превосходстве. Фаворит сохраняет преимущество, но результат не назначается заранее.</p><p>Оценка позиции — эвристика, а не проверенная вероятность победы. Турнирные отборочные, рейтинги и будущие патчи — правила игры.</p></section>`;};
const settingsBase13=settings;settings=function(){return `<section class="panel"><h2>v1.3 · живая карьера</h2><p>Общее развитие клубов, календарь серий, бюджеты ИИ, переговоры, решафлы по результатам, характеристики игроков, мета героев и адаптивные предметы. Автотренер, отборочные, рейтинг сезона, разведка, платные КВ BO2, автопаузы и разборы карт.</p><p>Добавлены Collapse, fy, Paparazi, xNova, Xxs. Их свободный статус и рейтинги заданы для карьеры, биографии и пулы взяты из профилей.</p><p>Освобождение контракта переводит игрока в свободные агенты без выплаты клубу. Существующие бюджеты и сыгранные результаты сохраняются.</p></section>`+settingsBase13();};
